const lengthOfLongestSubstring = function (s) {
  let map = {},
    start = 0,
    maxLen = 0;
  let arr = s.split("");
  for (let i = 0; i < s.length; i++) {
    let current = map[arr[i]];
    if (current != null && start <= current) {
      start = current + 1;
    } else {
      maxLen = Math.max(maxLen, i - start + 1);
    }
    map[arr[i]] = i;
  }
  return maxLen;
};

