async function* fetchPages(baseUrl, pageSize = 50) {
  let page = 1;
  let hasMore = true;
  while (hasMore) {
    const data = await fetch(`${baseUrl}?page=${page}&limit=${pageSize}`).then(
      (r) => r.json(),
    );
    yield data.items;
    hasMore = data.hasNextPage;
    page++;
  }
}

